   const opts=make('div','mkp-actions');button(opts,'托瑞希留坛，收好寄存笺',()=>finish('store'),true);button(opts,'留坛，只带走配方',()=>finish('recipe'));content.append(opts,make('p','mkp-hint','封坛后仍需静置待酿。本次不饮用，也不预设酒已熟成。'));
