 function view(focus=false,schedule=true){if(disposed)return;root.dataset.phase=s.phase;root.dataset.paused=String(s.paused);root.dataset.last=s.last;
  const idx={ready:0,catch:1,rest:1,mix:2,seal:3,done:3}[s.phase];[...steps.children].forEach((el,i)=>{el.classList.toggle('is-current',i===idx);if(i===idx)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
  const catching=s.phase==='catch',r=M.row(s),active=catching&&!s.paused;
  round.textContent=['catch','rest'].includes(s.phase)?'第 '+Math.min(3,Math.floor(s.index/6)+1)+' 阵 · '+Math.min(M.total,s.index+1)+' / '+M.total:'梅树下的酿酒台';count.textContent='白梅 '+s.picked.white+' · 绯梅 '+s.picked.pink+' · 晨露 '+s.picked.dew;
  const wind=r&&(s.guard===s.index?0:r.wind),final=r?M.target(s,true):50;
  forecast.textContent=catching&&r?M.kinds[r.kind]+' · '+(r.kind==='twig'?'移开盏，别接枯枝':Math.round(final)+'%处接取')+(wind?' · 风向'+(wind>0?'右':'左'):' · 风稳'):s.phase==='rest'?'花先收好，等下一阵风':'';
  trail.hidden=!catching;cup.hidden=!['ready','catch','rest'].includes(s.phase);marker.hidden=!catching;token.dataset.kind=r?.kind||'white';token.style.left=M.target(s)+'%';token.style.top=(22+s.progress*55)+'%';kind.textContent=M.kinds[r?.kind||'white'];marker.style.left=final+'%';cup.style.left=s.x+'%';slider.value=String(s.x);slider.setAttribute('aria-valuetext',Math.round(s.x)+'%处');
  left.disabled=!active||s.x<=10;right.disabled=!active||s.x>=90;step.disabled=!active;slider.disabled=!active;assist.disabled=!active||s.helps>=2||s.guard===s.index||!r||(!r.wind&&r.kind!=='twig');assist.textContent='巴卫协助 '+(2-s.helps)+'/2';pause.disabled=!catching;pause.textContent=s.paused?'继续':'暂停';slow.setAttribute('aria-pressed',String(s.slow));slow.textContent=s.slow?'慢速已开':'放慢';mode.textContent=s.mode==='step'?'切为自动':'切为逐步';finishEarly.disabled=!['catch','rest'].includes(s.phase);
  rangeLabel.hidden=steering.hidden=utility.hidden=!['catch','rest'].includes(s.phase);controls();
  const needle=content.querySelector('.mkp-needle'),sealRange=content.querySelector('[aria-label="纸封方向"]'),sealHint=content.querySelector('.mkp-seal-hint');if(needle)needle.style.transform='rotate('+s.angle+'deg)';if(sealRange)sealRange.value=String(s.angle);if(sealHint)sealHint.textContent='缺口 '+M.recipes[s.recipe].angle+'° · 当前 '+s.angle+'°';
  if(lastMessage!==s.message){lastMessage=s.message;talk.textContent=s.message;}if(focus)focusTitle();if(schedule){if(!active||s.mode==='step')stop();else if(!raf)raf=host.requestAnimationFrame(animate);}
 }
 function finish(delivery,cardOnly=false){const result=M.finish(s,delivery,cardOnly);if(!result){view();return;}stop();outcome=result;s.message=result.cardOnly?'瑞希把香笺晾在桌边。巴卫收起折扇，等你往回走。':'瑞希把小坛移到廊内。巴卫看你收好纸笺，才开口：“下次再来看。”';if(!recorded){recorded=true;try{if(options.onComplete?.({...result,activityVersion:'plum-1.33.0'})===false)storageNote='浏览器未允许本地保存，可用“导出香方”备份。';}catch{storageNote='香方回传未确认，可导出当前记录备份。';}}if(book.open)readBook();view(true);}
 slider.oninput=()=>{M.move(s,Number(slider.value));view();};
 const dragMove=e=>{const rect=stage.getBoundingClientRect();if(rect.width){M.move(s,(e.clientX-rect.left)/rect.width*100);view();}};
 listen(stage,'pointerdown',e=>{if(s.phase!=='catch'||s.paused||(e.pointerType&&e.button!==0))return;drag=e.pointerId;try{stage.setPointerCapture?.(e.pointerId);}catch{}dragMove(e);});listen(stage,'pointermove',e=>{if(drag===e.pointerId)dragMove(e);});for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(stage,type,()=>{drag=null;});
 listen(root,'keydown',e=>{if(e.defaultPrevented||e.altKey||e.ctrlKey||e.metaKey||e.target.matches?.('input,select,textarea'))return;if(['ArrowLeft','ArrowRight'].includes(e.key)&&s.phase==='catch'){e.preventDefault();M.move(s,s.x+(e.key==='ArrowLeft'?-10:10));view();}else if(e.code==='Space'&&!e.target.closest('button,summary')&&s.phase==='catch'){e.preventDefault();M.advance(s,.25);view();}});
