 const footer=make('div','mkd-footer');function button(parent,label,fn,primary=false){const b=make('button',primary?'mkd-primary':'',label);b.type='button';b.onclick=()=>{if(!disposed)fn();};parent.append(b);return b;}
 button(footer,'重新试搭',()=>{s=M.create();recorded=false;outcome=null;storageNote='';render(true);});button(footer,'导出梳妆笺',exportBook);button(footer,'回到地图',()=>options.onClose?.());
