const STEALTH_ART_URL="https://cdn.jsdelivr.net/gh/AliceNekoqqq/Aliceneko-Map-Plugin@635a36c959bd154d90af1bf3c262d63912d73e1c/mikage-shrine/assets/activities/stealth-v136-props.webp";
