 const stage=make('div','mkf-stage'),bg=make('img','mkf-scene'),art=options.art?.R08,url=typeof art==='string'?art:art?.[options.period||'day'];bg.alt='鸣神殿檐外雷光与台阶';if(typeof url==='string'&&/^https:\/\/(cdn\.jsdelivr\.net|raw\.githubusercontent\.com)\//.test(url)){bg.src=url;bg.onerror=()=>bg.remove();stage.append(bg);}
