 const yard=make('div','mkf-yard'),dry=make('div','mkf-dry','檐下干地'),route=make('div','mkf-path','去廊内 →'),shade=make('div','mkf-shade'),mat=make('div','mkf-mat'),fox=make('div','mkf-fox'),plate=make('div','mkf-plate','笹饼');fox.setAttribute('role','img');fox.setAttribute('aria-label','银白幼狐巴卫');mat.setAttribute('role','img');mat.setAttribute('aria-label','避风垫子，可拖动或用下方位置滑条调整');yard.append(dry,route,shade,mat,plate,fox);
 const net=make('div','mkf-net'),netLabel=make('p','mkf-net-label');net.append(make('div','mkf-mesh'),netLabel);const knots=[];for(let i=0;i<3;i++){const b=make('button','mkf-knot');b.type='button';b.dataset.knot=String(i);b.onclick=e=>{if(e.detail===0)take(i);};knots.push(b);net.append(b);}yard.append(net);
 const figures=make('div','mkf-companions'),player=make('span');figures.append(player);stage.append(hud,yard,figures);
 function button(parent,label,fn,primary=false){const b=make('button',primary?'mkf-primary':'',label);b.type='button';b.onclick=()=>{if(!disposed)fn();};parent.append(b);return b;}
 const content=make('div','mkf-content'),talk=make('p','mkf-talk');talk.setAttribute('role','status');talk.setAttribute('aria-live','polite');talk.setAttribute('aria-atomic','true');
 const tools=make('div','mkf-actions'),pause=button(tools,'暂停',()=>{M.pause(s,!s.paused);view(true);}),early=button(tools,'今天先守到这里',()=>{M.stop(s);view(true);});
 const footer=make('div','mkf-footer');button(footer,'重新守一回',()=>{release();s=M.create();recorded=false;outcome=null;storageNote='';screenKey='';view(true);});button(footer,'导出守护笺',exportBook);button(footer,'回到地图',()=>options.onClose?.());
 const book=make('details','mkf-book'),bookBody=make('div');book.append(make('summary','','旧物回忆册'),bookBody);listen(book,'toggle',()=>{if(book.open)readBook();});root.append(head,steps,stage,content,tools,talk,footer,book);container.append(root);
 const artProbe=new host.Image();artProbe.onload=()=>{if(!disposed)root.classList.add('mkf-art-ready');};artProbe.onerror=()=>{if(!disposed)root.classList.add('mkf-art-missing');};artProbe.src=FOX_ART_URL;
 function readBook(){bookBody.replaceChildren();const entries=Object.values(options.getMemoryBook?.().entries||{});if(!entries.length)bookBody.append(make('p','','还没有守护笺。离开前可以留下一页。'));for(const e of entries)bookBody.append(make('p','',String(e.item||e.id)+' · '+String(e.detail||e.line||'')));}
