 listen(net,'pointermove',e=>{if(netDrag!==e.pointerId||s.phase!=='net'||s.paused)return;for(let i=0;i<3;i++){const r=knots[i].getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom&&lastKnot!==i){lastKnot=i;take(i);break;}}});
