 function view(focus=false){if(disposed)return;const focused=root.getRootNode().activeElement,name=content.contains(focused)&&focused?.tagName==='BUTTON'?focused.textContent:null;root.dataset.phase=s.phase;root.dataset.round=String(s.round);root.dataset.cleared=String(s.cleared);root.dataset.paused=String(s.paused);const q=M.issues(s);root.dataset.crossings=String(q.crossings);root.dataset.crowded=String(q.crowded);progress.textContent='理线 '+s.cleared+' / 3';status.textContent=s.paused?'暂停中':s.phase==='untangle'?'交叉 '+q.crossings+' · 挤结 '+q.crowded:s.phase==='weave'?'穿绳 '+s.weave+' / 3':'祈愿留在纸上';board.hidden=s.phase!=='untangle';weave.hidden=!['weave','closing','done'].includes(s.phase);wish.hidden=s.phase!=='ready';wish.textContent=M.wishes[s.wish];board.classList.toggle('mkt-paused',s.paused);guide.textContent=s.weave<3?'纸样：上 → 下 → 上 · 下一穿'+(['上层','下层','上层'][s.weave]):s.tied?'红线结已收好':s.tension<35?'线圈还松着':s.tension>65?'收得太紧了':'松紧正好，可以收结';weave.hidden=weave.hidden||(s.phase==='closing'||s.phase==='done')&&!s.tied;steps.childNodes.forEach((el,i)=>el.classList.toggle('is-current',i===(s.phase==='ready'||s.phase==='untangle'?0:s.phase==='weave'?1:2)));tools.hidden=!['untangle','weave','closing'].includes(s.phase);pause.textContent=s.paused?'继续':'暂停';stop.hidden=s.phase==='closing';screens();syncNodes();draw();if(talk.textContent!==s.message)talk.textContent=s.message;if(name&&focused&&!focused.isConnected)[...content.querySelectorAll('button')].find(b=>b.textContent===name)?.focus({preventScroll:true});if(book.open&&s.phase==='done')readBook();if(focus)focusContent();}
