 const stage=make('div','mkfl-stage'),bg=make('img','mkfl-scene');bg.alt='缘结参道的祭典灯路';bg.onerror=()=>{bg.hidden=true;};bg.onload=()=>{if(!disposed)bg.hidden=false;};stage.append(bg);
