 const hud=make('div','mkfl-hud'),progress=make('span'),chain=make('span');hud.append(progress,chain);
 const lamps=make('div','mkfl-lamps'),lampButtons=[];for(let i=0;i<8;i++){const b=make('button','mkfl-lamp');b.type='button';b.dataset.lamp=String(i);b.setAttribute('aria-label','第'+(i+1)+'盏参道小灯');b.style.left=[13,38,63,87][i%4]+'%';b.style.top=(i<4?24:75)+'%';b.append(make('i'),make('span','',String(i+1)));b.onclick=e=>{if(e.detail===0){M.select(s,i);view();}};lamps.append(b);lampButtons.push(b);}
 const cue=make('button','mkfl-cue','✦');cue.type='button';cue.setAttribute('aria-label','接住这一拍');cue.onclick=()=>{if(M.hit(s))view(s.phase==='encore');else view();};
 const freeSky=make('div','mkfl-free-sky');freeSky.setAttribute('aria-hidden','true');const clock=make('p','mkfl-clock'),actors=make('div','mkfl-actors'),player=make('span'),tomoe=make('span');actors.append(player,tomoe);stage.append(hud,lamps,freeSky,cue,clock,actors);
 const content=make('div','mkfl-content'),talk=make('p','mkfl-talk');talk.setAttribute('role','status');talk.setAttribute('aria-live','polite');talk.setAttribute('aria-atomic','true');
